<script setup>
import { computed, ref } from 'vue'
import { savedGameHit } from '@/utils/cageGame/session'
import { createFieldMapper, fenceAt, baseCoords } from '@/utils/cageGame/ballFlight'
import { summarizeSwings } from '@/utils/cageGame/hitClassification'
const props=defineProps({rows:{type:Array,default:()=>[]},field:Object,playerId:String,playerName:String, showContinue:{type:Boolean,default:true}})
const emit=defineEmits(['continue'])
const reviewId=ref(''),replay=ref(0)
const reducedMotion=typeof window !== 'undefined' && window.matchMedia?.('(prefers-reduced-motion: reduce)').matches
const hits=computed(()=>props.rows.filter(r=>r.user_id===props.playerId).slice().sort((a,b)=>Number(a.sort)-Number(b.sort)).map(r=>savedGameHit(r,props.field)))
const active=computed(()=>hits.value.find(h=>h.id===reviewId.value)||hits.value.at(-1))
const summary=computed(()=>summarizeSwings(hits.value,props.field.levelId))
const mapper=computed(()=>createFieldMapper(800,540,{...props.field,maxDistanceFt:Math.max(...Object.values(props.field.fences),...hits.value.map(h=>h.distanceFt))*1.15}))
const xy=p=>`${p.px},${p.py}`
const fence=computed(()=>Array.from({length:91},(_,i)=>mapper.value.mapBall(fenceAt(i-45,props.field.fences),i-45)))
const boundary=computed(()=>[mapper.value.home,...fence.value,mapper.value.home].map(xy).join(' '))
const diamond=computed(()=>Object.values(baseCoords(props.field.basePathFt)).map(([x,y])=>xy(mapper.value.mapFeet(x,y))).join(' '))
const landing=computed(()=>active.value?mapper.value.mapBall(active.value.distanceFt,active.value.sprayAngle):mapper.value.home)
const flightPath=computed(()=>`M ${xy(mapper.value.home)} Q ${(mapper.value.home.px+landing.value.px)/2},${Math.min(mapper.value.home.py,landing.value.py)-40} ${xy(landing.value)}`)
</script>
<template><section class="game-review"><header><div><p>CAGE GAME MODE · {{ field.levelLabel }}</p><h2>{{ playerName }} · {{ active?.result || 'Ready to hit' }}</h2><p>Simulated outcome · {{ active ? `${active.ev} mph · ${active.launchAngle}° launch · ${active.sprayAngle}° spray · ${Math.round(active.distanceFt)} ft estimated distance` : 'Save a cage swing to see its flight and result.' }}</p></div><button v-if="showContinue" @click="emit('continue')">Continue scoring →</button></header><svg viewBox="0 0 800 540" role="img" :aria-label="`Game field and ${playerName}'s saved hits`"><rect width="800" height="540" fill="#0b2332" rx="24"/><polygon :points="boundary" fill="#276847" stroke="#c2e8b8" stroke-width="3"/><polygon :points="diamond" fill="#ad8559" stroke="white" stroke-width="2"/><circle :cx="mapper.mapFeet(0,field.pitchingFt).px" :cy="mapper.mapFeet(0,field.pitchingFt).py" r="5" fill="#e5d0ad"/><template v-for="(distance,key) in field.fences" :key="key"><text :x="mapper.mapBall(distance,{lineL:-45,gapL:-22.5,center:0,gapR:22.5,lineR:45}[key]).px" :y="mapper.mapBall(distance,{lineL:-45,gapL:-22.5,center:0,gapR:22.5,lineR:45}[key]).py-9" text-anchor="middle" fill="white" font-size="14">{{ distance }} ft</text></template><circle v-for="hit in hits" :key="hit.id" :cx="mapper.mapBall(hit.distanceFt,hit.sprayAngle).px" :cy="mapper.mapBall(hit.distanceFt,hit.sprayAngle).py" r="5" fill="#74ddeb"/><template v-if="active"><path :d="flightPath" fill="none" stroke="#ffe695" stroke-width="3" stroke-dasharray="7 5"/><circle :key="`${active.id}-${replay}`" :cx="reducedMotion ? landing.px : 0" :cy="reducedMotion ? landing.py : 0" r="8" fill="white" stroke="#ff2451" stroke-width="2"><animateMotion v-if="!reducedMotion" :path="flightPath" dur="1.6s" fill="freeze" /></circle></template></svg><div class="game-actions"><label>Review swing<select v-model="reviewId"><option value="">Latest swing</option><option v-for="(hit,index) in hits" :key="hit.id" :value="hit.id">{{ index+1 }} · {{ hit.result }} · {{ hit.ev }} mph</option></select></label><button :disabled="!active" @click="replay++">Replay flight</button></div><p class="summary">Today’s session · {{ summary.total }} hits · {{ summary.barrels }} barrels · Best EV {{ summary.bestEv }} mph · Average EV {{ summary.avgEv.toFixed(1) }} mph</p><p>Ground balls {{ summary.trajectoryPct.gb }}% · Line drives {{ summary.trajectoryPct.ld }}% · Fly balls {{ summary.trajectoryPct.fly }}%</p><div v-if="active?.outcome.probabilities" class="probabilities"><span v-for="(chance,type) in active.outcome.probabilities" :key="type">{{ {out:'Out',single:'Single',double:'Double',triple:'Triple',homeRun:'Home run'}[type] }}: {{ chance }}%</span></div><p class="help">Simulations are practice feedback, not official game results. Replaying or reopening a saved hit keeps its outcome.</p></section></template>
<style scoped>.game-review{background:#10182b;color:white;border:1px solid #66748b;border-radius:24px;padding:20px;margin:18px 0}header{display:flex;justify-content:space-between;gap:15px;flex-wrap:wrap}h2{font-size:26px;font-weight:800}p{margin:8px 0}svg{display:block;width:100%;max-height:600px;margin:12px auto}button,select{background:#293651;color:white;border:1px solid #8d9bb1;border-radius:15px;padding:12px;min-height:44px}button{font-weight:750}header button{background:#ff2451}.game-actions,.probabilities{display:flex;gap:12px;flex-wrap:wrap;align-items:center}.probabilities span{background:#25354e;border-radius:14px;padding:10px}.help{font-size:12px;color:#bac6d9}.summary{font-weight:750}select{margin-left:10px;max-width:100%}@media(prefers-reduced-motion:reduce){svg{scroll-behavior:auto}}</style>
